def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    chairs = image_patch.find("chair")
    tables = image_patch.find("table")

    if not chairs or not tables:
        return image_patch

    main_table = [t for t in tables if t.simple_query("Is this the main table?").lower() == "yes"]
    if not main_table:
        return image_patch

    main_table = main_table[0]

    fully_shown_chairs = []
    for chair in chairs:
        if chair.overlaps_with(main_table.left, main_table.lower, main_table.right, main_table.upper):
            fully_shown_chairs.append(chair)

    return fully_shown_chairs[0] if fully_shown_chairs else chairs[0]

